const body = $json.body ?? $json;

const current = body.current ?? {};
const history = Array.isArray(body.history) ? body.history : [];

return [
  {
    json: {
      current,
      history,
      language: body.language ?? 'es',
      forecastPeriods: Number(body.forecastPeriods ?? 3)
    }
  }
];
